  /** @type {unknown} */
  value = null;

  /** @type {string | number | import("@ember/template").TrustedHTML | null | undefined} */
  headerTitle = null;

  /** @type {string | null | undefined} */
  headerLang = null;

  /** @type {string | number | import("@ember/template").TrustedHTML | null | undefined} */
  headerLabel = null;

  /** @type {string | null} */
  id = null;

