      </div>
    {{else}}
      {{#if this.item.icon}}
        <div
          class="select-kit-selected-name selected-name choice"
          lang={{this.lang}}
        >
          {{dIcon this.item.icon}}
        </div>
      {{/if}}
    {{/if}}
  </template>
